import {metrics,TODAY} from './data.js?v=20260919-residents';
import {renovationSteps,buildingRenovationSteps,relocationSteps,renovationLabels,residentLabels,renovationMetrics} from './renovation-data.js?v=20260919-residents';
import {e,num,money,date,icon,link,button,title,card,panel,progress,table,info,timeline,workflow,empty} from './ui.js?v=20260919-residents';
const rBadge=(key,kind='plan')=>{const [label,tone]=(kind==='resident'?residentLabels:renovationLabels)[key]||[key,'gray'];return `<span class="badge ${tone}"><span class="status-dot"></span>${label}</span>`;};
const unit=id=>id?link('/units/'+id,`<span class="unit-code">${e(id)}</span>`):'<span class="muted">لم تُخصص</span>';
const rb=(text,action,id,cls='btn primary')=>button(text,action,cls,`data-id="${e(id)}"`);
export function usageBadge(u){const map={RENTAL:['تأجير','gray'],TEMPORARY_HOUSING:['سكن مؤقت','blue'],MAINTENANCE:['صيانة','amber'],UNAVAILABLE:['غير متاحة','gray']};const [text,tone]=map[u.usageType||'RENTAL'];return `<span class="badge ${tone}">${u.usageType==='TEMPORARY_HOUSING'?icon('home'):''}${text}</span>`;}
export function renovationSummary(d){const m=renovationMetrics(d);return panel('برنامج تطوير المباني',`<div class="renovation-summary">${[['مباني مخطط صيانتها',m.planned,'building'],['مباني تحت الصيانة',m.underWork,'wrench'],['أسر يشملها الانتقال المؤقت',m.affected,'users'],['أسر تم نقلها',m.moved,'route'],['وحدات انتقال جاهزة',m.poolReady,'home'],['أسر عادت لوحداتها',m.returned,'check']].map(([label,v,ico])=>`<div><span class="muted">${icon(ico)} ${label}</span><strong>${num(v)}</strong></div>`).join('')}</div><div class="renovation-progress"><div><span>إنجاز برنامج التجديد</span><strong>${m.progress}%</strong></div>${progress(m.progress)}<p>إنجاز موزون بحسب نطاق أعمال المراحل · ${m.current} أسرة في السكن المؤقت حالياً</p></div>`,link('/renovation','عرض برنامج التجديد '+icon('left'),'text-link'),'section-gap');}
export function poolSection(d){const m=renovationMetrics(d),vacant=metrics(d).vacant;return panel('مخزون السكن المؤقت',`<div class="pool-stats">${[[vacant,'غير مؤجرة تعاقدياً'],[m.poolTotal,'مخصصة للسكن المؤقت'],[m.poolUsed,'مستخدمة حالياً'],[m.poolReady,'جاهزة للانتقال'],[m.poolReserved,'محجوزة']].map(([v,t],i)=>`<div><strong class="${i===3?'green-text':''}">${num(v)}</strong><small>${t}</small></div>`).join('')}</div><div class="pool-note">${icon('home')}السكن المؤقت جزء من الوحدات غير المؤجرة، ولا ينشئ عقداً جديداً للمستأجر. تبقى الوحدة الأصلية مرتبطة بعقده.</div>`,button('استعراض الوحدات '+icon('left'),'pool-modal','text-link'));}
function planCard(d,p){const b=d.buildings.find(b=>b.id===p.buildingId),m=metrics(d,p.buildingId),r=renovationMetrics(d,p.id),people=d.renovation.residents.filter(x=>x.buildingId===p.id).reduce((s,x)=>s+(d.tenants.find(t=>t.id===x.tenantId)?.family||0),0);return link('/renovation/'+p.id,`<div class="building-head"><span class="icon-box">${icon('building')}</span><div><h2>${e(b.name)}</h2><p>${b.zone} · المرحلة ${p.phase}</p></div>${rBadge(p.status)}</div><div class="building-stats"><div><strong>${m.total}</strong><small>إجمالي الوحدات</small></div><div><strong>${m.occupied}</strong><small>وحدات مشغولة</small></div><div><strong>${r.affected||'—'}</strong><small>أسر متأثرة</small></div></div><div class="renovation-card-info"><span>${icon('wrench')}${e(p.type)}</span><span>${icon('users')}${r.affected?people+' فرداً ضمن الأسر المتأثرة':'تحديد السكان بعد التقييم'}</span><span>${icon('calendar')}${date(p.start)} — ${date(p.end)}</span></div><div class="building-progress-label"><span class="muted">نسبة إنجاز الأعمال</span><strong>${p.progress}%</strong></div>${progress(p.progress)}<div class="building-bottom"><span>${r.current} أسر في السكن المؤقت</span><span class="green-text">متابعة البرنامج ${icon('left')}</span></div>`,'building-card');}
export function renovationDashboard(d,q){const m=renovationMetrics(d),sel=q.get('status')||'ALL';const plans=d.renovation.plans.filter(p=>(sel==='ALL'||p.status===sel)&&(`${p.id} ${p.type}`).toLowerCase().includes((q.get('q')||'').toLowerCase()));return title('تطوير الأصول · RENOVATION & RELOCATION','برنامج تجديد وصيانة المباني','إدارة أعمال التجديد والصيانة مع نقل السكان مؤقتاً وإعادتهم بعد اكتمال الأعمال.',button(icon('home')+' وحدات السكن المؤقت','pool-modal','btn'))+
 `<section class="renovation-banner"><div><span class="badge green">التشغيل مستمر</span><h2>نجدد المباني، ونحافظ على استقرار السكان.</h2><p>التنفيذ على مراحل، مع وحدة بديلة لكل أسرة وخطة واضحة للعودة.</p></div><div class="renovation-banner-progress"><strong>${m.progress}<small>%</small></strong><span>إنجاز البرنامج</span>${progress(m.progress)}</div></section>`+
 `<div class="stats-grid renovation-stat-grid">${card('مبانٍ ضمن البرنامج',m.planned,m.underWork+' مبانٍ في مرحلة التنفيذ','building')}${card('الأسر المتأثرة',m.affected,'تشمل جميع أسر المرحلة الحالية','users')}${card('تم انتقالها',m.moved,`${m.current} حالياً بالسكن المؤقت · ${m.returned} عادت`,'route')}${card('بانتظار النقل',m.pending,'إشعار وتخصيص وتنسيق الانتقال','clock','amber')}</div>`+
 panel('من فحص المبنى إلى عودة السكان',workflow(renovationSteps,5,true),'<span class="small muted">مسار الدفعة الجارية · التنفيذ على مراحل</span>')+
 `<section class="section-gap"><div class="toolbar"><h2>برامج المباني</h2><div class="toolbar-controls"><div class="filter-tabs" role="group" aria-label="حالة التجديد">${[['ALL','الكل'],['PLANNING','تخطيط'],['RENOVATION','تحت الصيانة'],['INSPECTION','فحص الجودة'],['RETURN','إعادة السكان'],['COMPLETED','مكتمل']].map(([key,label])=>button(label,'filter',`filter-tab ${key===sel?'active':''}`,`data-key="status" data-value="${key}" aria-pressed="${key===sel}"`)).join('')}</div><label class="search-box">${icon('search')}<input type="search" data-search="q" value="${e(q.get('q')||'')}" placeholder="ابحث بالمبنى أو نوع العمل..." aria-label="البحث في برامج التجديد"/></label></div></div><div class="building-grid">${plans.length?plans.map(p=>planCard(d,p)).join(''):empty()}</div></section>`+
 `<div class="section-gap">${poolSection(d)}</div>`+
 `<div class="two-col equal section-gap">${panel('خطة التنفيذ المرحلية',`<ol class="phase-timeline">${[['01','A01 · A02','سبتمبر – أكتوبر 2026','التنفيذ الجاري'],['02','A03 · A04','نوفمبر – ديسمبر 2026','مخطط'],['03','A05 · A06','يناير – فبراير 2027','مخطط'],['04','A07 · A08','مارس – أبريل 2027','مخطط'],['05','A09 · A10','مايو – يونيو 2027','مخطط'],['06','A11 · A12','يوليو – أغسطس 2027','مخطط']].map(([n,bs,time,status],i)=>`<li><span class="phase-number ${i===0?'active':''}">${n}</span><div><strong class="ltr">${bs}</strong><p>${time}</p></div><span class="badge ${i===0?'green':'gray'}">${status}</span></li>`).join('')}</ol>`)}${panel('نوعان من أعمال الصيانة',`<div class="work-type"><span class="icon-box blue">${icon('wrench')}</span><div><h3>الصيانة التشغيلية</h3><p>بلاغ محدد لمعالجة عطل يومي في الوحدة.</p><div class="step-group"><span>تكييف</span><span>سباكة</span><span>كهرباء</span></div>${link('/maintenance','انتقل إلى بلاغات الصيانة '+icon('left'),'text-link')}</div></div><div class="work-type"><span class="icon-box">${icon('building')}</span><div><h3>برنامج تجديد المباني</h3><p>نطاق أعمال كبير، انتقال مؤقت للسكان، وفحص قبل العودة.</p><div class="step-group"><span>واجهات</span><span>عزل</span><span>تجديد داخلي</span><span>أعمال إنشائية</span><span>تجديد شامل</span></div></div></div>`)}</div>`+
 panel('استمرارية التشغيل أثناء التجديد',`<div class="continuity-flow">${[[metrics(d).total,'إجمالي الوحدات','building'],[metrics(d).occupied,'وحدة مشغولة','key'],[m.affected,'أسرة ضمن نطاق البرنامج','users'],[m.poolTotal,'وحدة في مخزون السكن المؤقت','home']].map(([v,l,ico])=>`<div><span class="icon-box">${icon(ico)}</span><strong>${v}</strong><small>${l}</small></div>`).join('')}</div><div class="continuity-steps">${['تحديد الوحدات المتأثرة','تخصيص جزء من الشاغر للسكن المؤقت','تنفيذ التجديد على مراحل','فحص الوحدات وإعادة السكان','تحرير الوحدات المؤقتة للإيجار'].map((text,i)=>`<span>${i+1}. ${text}</span>`).join(icon('left'))}</div><p class="continuity-caption">نستفيد من الوحدات المتاحة لاستمرار تشغيل المجمع خلال التجديد، ثم نعيد الوحدات البديلة إلى مخزون التأجير وفق خطة المراحل.</p>`);
}
function residentAction(r){if(r.status==='NOTIFIED')return rb('تخصيص وحدة بديلة','relocation-assign',r.id,'btn small');if(r.status==='ASSIGNED')return rb('تأكيد الانتقال','relocation-move',r.id,'btn small primary');if(r.status==='READY')return rb('اعتماد العودة','relocation-return',r.id,'btn small primary');return r.status==='RETURNED'?'<span class="green-text small">اكتملت العودة</span>':'<span class="muted small">بانتظار فحص الجودة</span>';}
export function residentsTable(d,rs){return rs.length?table(['المستأجر','الوحدة الأصلية','الوحدة المؤقتة','تاريخ النقل','العودة المتوقعة','حالة الصيانة','حالة المستأجر','الإجراء التالي'],rs.map(r=>{const p=d.renovation.plans.find(p=>p.id===r.buildingId),t=d.tenants.find(t=>t.id===r.tenantId);return `<tr><td>${link('/tenants/'+t.id,`<span class="cell-title">${e(t.name)}</span><span class="cell-sub">${t.family} أفراد</span>`)}</td><td>${unit(r.originalUnitId)}</td><td>${unit(r.temporaryUnitId)}</td><td>${date(r.moveDate)}</td><td>${r.status==='RETURNED'?`<span class="green-text">عادت ${date(r.actualReturn)}</span>`:date(r.expectedReturn)}</td><td>${r.status==='RETURNED'?rBadge('COMPLETED'):rBadge(p.status)}</td><td>${rBadge(r.status,'resident')}</td><td>${residentAction(r)}</td></tr>`;})):empty('لا توجد أسر في هذه القائمة','يتم تحديد الأسر المتأثرة بعد فحص نطاق أعمال المبنى.');}
export function renovationDetail(d,id,q){const p=d.renovation.plans.find(p=>p.id===id);if(!p)return title('برنامج التجديد','لم يتم العثور على المبنى','',link('/renovation','العودة للبرنامج','btn'));const m=renovationMetrics(d,id),u=metrics(d,id),rs=d.renovation.residents.filter(r=>r.buildingId===id),sel=q.get('resident')||'ALL',filtered=rs.filter(r=>sel==='ALL'||r.status===sel||(sel==='RELOCATED'&&r.status==='READY')||(sel==='PENDING'&&['NOTIFIED','ASSIGNED'].includes(r.status)));const step={PLANNING:0,ASSESSMENT:0,RELOCATION:3,RENOVATION:4,INSPECTION:5,RETURN:6,COMPLETED:7}[p.status];let next='بدء فحص المبنى وتحديد نطاق الأعمال',action=rb('بدء تقييم المبنى','renovation-assess',id);if(p.status==='ASSESSMENT'){next='تحديد نطاق العمل والأسر المتأثرة قبل النقل';action=link('/renovation','العودة لخطة البرنامج','btn');}if(p.status==='RENOVATION'){next=m.pending?`تنسيق انتقال ${m.pending} أسرة بالتوازي مع الأعمال المرحلية`:'اعتماد اكتمال أعمال التجديد وتجهيز فحص الجودة';action=m.pending?link('/renovation/'+id+'?resident=PENDING','متابعة الأسر بانتظار النقل '+icon('left'),'btn primary'):rb('اعتماد اكتمال الصيانة','renovation-complete',id);}if(p.status==='INSPECTION'){next='جاهز للفحص — مراجعة جودة الوحدات الأصلية';action=rb('اعتماد فحص الجودة','renovation-inspect',id);}if(p.status==='RETURN'){next='تنسيق عودة الأسر إلى وحداتها الأصلية';action=link('/renovation/'+id+'?resident=READY','عرض الأسر الجاهزة للعودة '+icon('left'),'btn primary');}if(p.status==='COMPLETED'){next='اكتملت أعمال المبنى وعادت جميع الأسر';action=link('/buildings/'+id,'عرض المبنى','btn');}
 return link('/renovation',icon('chevron')+' برنامج التجديد','back-link')+title('تجديد المبنى · المرحلة '+p.phase,`برنامج تجديد <span class="ltr">${id}</span>`,p.type+' · '+date(p.start)+' — '+date(p.end),rBadge(p.status))+
 `<div class="stats-grid renovation-detail-stats">${card('إجمالي الوحدات',u.total,'الوحدات داخل المبنى','building')}${card('الأسر المتأثرة',m.affected,'ضمن نطاق العمل','users')}${card('تم نقلها',m.moved,`${m.current} في السكن المؤقت حالياً`,'route')}${card('بانتظار النقل',m.pending,'إشعار أو وحدة مخصصة','clock','amber')}${card('جاهزة للعودة',m.readyToReturn,'اجتازت فحص الجودة','check')}${card('نسبة الإنجاز',p.progress+'%',m.returned+' أسرة عادت لوحدتها','chart')}</div>`+
 panel('مراحل التنفيذ',workflow(buildingRenovationSteps,step),'<span class="small muted">المرحلة الأبعد للدفعات الجاري تنفيذها</span>')+
 `<section class="next-action"><div><p>المرحلة الحالية: ${renovationLabels[p.status][0]}</p><h3>${next}</h3><div class="responsible">المسؤول: ${e(p.manager)}</div></div>${action}</section>`+
 `<div class="two-col equal">${panel('نطاق العمل والمتابعة',`<div class="panel-body"><p class="small muted">${e(p.scope)}</p><div class="building-progress-label" style="margin-top:20px"><span>تقدم أعمال المبنى</span><strong>${p.progress}%</strong></div>${progress(p.progress)}</div>`)}${panel('خطة انتقال السكان',info([['بداية الأعمال',date(p.start)],['الانتهاء المتوقع',date(p.end)],['منسق السكان','سارة العبدالله'],['الإشغال الأصلي',u.occupied+' وحدة'],['الأسر في السكن المؤقت',m.current+' أسرة'],['الأسر التي عادت',m.returned+' أسرة']]))}</div>`+
 `<div class="toolbar"><h2>السكان المتأثرون</h2><div class="filter-tabs" role="group" aria-label="حالة السكان">${[['ALL','الجميع',rs.length],['PENDING','بانتظار النقل',m.pending],['RELOCATED','في السكن المؤقت',m.current],['READY','جاهزون للعودة',m.readyToReturn],['RETURNED','عائدون',m.returned]].map(([key,label,count])=>button(label+` <span>${count}</span>`,'filter',`filter-tab ${key===sel?'active':''}`,`data-key="resident" data-value="${key}"`)).join('')}</div></div><section class="panel">${residentsTable(d,filtered)}</section>`;
}
export function tenantRelocationSection(d,tenantId){const r=d.renovation.residents.find(r=>r.tenantId===tenantId);if(!r)return '';const p=d.renovation.plans.find(p=>p.id===r.buildingId),step={NOTIFIED:0,ASSIGNED:1,RELOCATED:3,READY:4,RETURNED:5}[r.status];return panel('الانتقال المؤقت',`<div class="relocation-person"><span class="icon-box blue">${icon('home')}</span><div><strong>${r.status==='RETURNED'?'عاد المستأجر إلى وحدته الأصلية':'الأسرة ضمن برنامج تجديد المبنى '+r.buildingId}</strong><p>سبب الانتقال: ${e(r.reason)}</p></div>${rBadge(r.status,'resident')}</div>${info([['الوحدة الأصلية',unit(r.originalUnitId)],['الوحدة المؤقتة',unit(r.temporaryUnitId)],['تاريخ الانتقال',date(r.moveDate)],['العودة المتوقعة',date(r.expectedReturn)],['المبنى',link('/renovation/'+r.buildingId,'برنامج تجديد '+r.buildingId)],['تقدم الصيانة',`<span>${r.status==='RETURNED'?100:p.progress}%</span>${progress(r.status==='RETURNED'?100:p.progress)}`]])}<div class="relocation-action">${residentAction(r)}${r.actualReturn?`<span class="small muted">تاريخ العودة الفعلي: ${date(r.actualReturn)}</span>`:''}${link('/renovation/'+r.buildingId,'متابعة برنامج المبنى '+icon('left'),'text-link')}</div>${workflow(relocationSteps,step)}${timeline([...r.history].reverse())}`,link('/renovation','برنامج التجديد '+icon('left'),'text-link'),'section-gap');}
export function temporaryUnitSection(d,u){const p=d.renovation.pool.find(p=>p.unitId===u.id);if(!p)return '';const r=d.renovation.residents.find(r=>r.id===p.residentId),t=r?d.tenants.find(t=>t.id===r.tenantId):null;const state={READY:['جاهزة للانتقال','green'],USED:['مستخدمة حالياً','blue'],RESERVED:['محجوزة لأسرة','amber']}[p.state];return panel('الوحدة ضمن مخزون السكن المؤقت',`<div class="relocation-person"><span class="icon-box blue">${icon('home')}</span><div><strong>سكن بديل خلال تجديد الوحدات الأصلية</strong><p>مخصصة لاستمرارية السكن ضمن برنامج تطوير المباني.</p></div><span class="badge ${state[1]}">${state[0]}</span></div>${r?info([['الأسرة',link('/tenants/'+t.id,e(t.name))],['الوحدة الأصلية',unit(r.originalUnitId)],['تاريخ الانتقال',date(r.moveDate)],['العودة المتوقعة',date(r.expectedReturn)]]):`<div class="panel-body"><p class="small muted" style="margin-bottom:14px">هذه الوحدة جاهزة لتخصيصها لأسرة ضمن برنامج التجديد.</p>${rb('إعادة الوحدة لمخزون التأجير','release-temporary',u.id,'btn')}</div>`}`,link('/renovation','برنامج التجديد '+icon('left'),'text-link'),'section-gap');}
export function poolTable(d){return table(['الوحدة المؤقتة','النوع','الحالة','الأسرة','المبنى الأصلي'],d.renovation.pool.map(p=>{const r=d.renovation.residents.find(r=>r.id===p.residentId),u=d.units.find(u=>u.id===p.unitId),t=r?d.tenants.find(t=>t.id===r.tenantId):null;return `<tr><td>${unit(p.unitId)}</td><td>${u.bedrooms===2?'غرفتا نوم':'غرفة نوم'}</td><td><span class="badge ${p.state==='READY'?'green':p.state==='USED'?'blue':'amber'}">${p.state==='READY'?'جاهزة':p.state==='USED'?'مستخدمة':'محجوزة'}</span></td><td>${t?link('/tenants/'+t.id,e(t.name)):'—'}</td><td>${r?link('/renovation/'+r.buildingId,r.buildingId):'—'}</td></tr>`;}));}
